code='''def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    bg = max(counts, key=counts.get)

    def endpoint_score(r, c, other, color):
        score = 0
        for rr in range(max(0, r - 1), min(h, r + 2)):
            for cc in range(max(0, c - 1), min(w, c + 2)):
                if (rr, cc) != (r, c) and (rr, cc) != other and grid[rr][cc] not in (bg, color):
                    score += 1
        return score

    for dr, dc in ((1, 1), (1, -1)):
        for r in range(h):
            for c in range(w):
                color = grid[r][c]
                if color == bg:
                    continue
                pr, pc = r - dr, c - dc
                if 0 <= pr < h and 0 <= pc < w and grid[pr][pc] == color:
                    continue
                run = [(r, c)]
                nr, nc = r + dr, c + dc
                while 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == color:
                    run.append((nr, nc))
                    nr += dr
                    nc += dc
                if len(run) < 2:
                    continue
                start, end = run[0], run[-1]
                sscore = endpoint_score(*start, end, color)
                escore = endpoint_score(*end, start, color)
                if escore > sscore:
                    rr, cc, step_r, step_c = start[0] - dr, start[1] - dc, -dr, -dc
                else:
                    rr, cc, step_r, step_c = end[0] + dr, end[1] + dc, dr, dc
                while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == bg:
                    out[rr][cc] = color
                    rr += step_r
                    cc += step_c
    return out
'''
